seen = set()
for item in R:
    rid, check, loc, status, evidence = item[:5]
    fix = item[5] if len(item) > 5 else ""
    assert rid not in seen, rid
    seen.add(rid)
    row = {"id": rid, "check": check, "location": loc, "status": status, "evidence": evidence}
    if status != P:
        row["fix"] = fix
    rows.append(row)

npass = sum(1 for r in rows if r["status"] == P)
nfail = sum(1 for r in rows if r["status"] == "FAIL")
